<?php
namespace App\Http\Middleware;
use App\Models\{SecurityEvent}; use App\Services\ApiResponse; use Closure; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class PreventReplay { public function handle(Request $request,Closure $next){$nonce=$request->header('X-Request-Nonce');$timestamp=(int)$request->header('X-Request-Timestamp');$installation=$request->attributes->get('installation');if(!$nonce||!$timestamp||abs(now()->timestamp-$timestamp)>config('office.nonce_lifetime_seconds'))return ApiResponse::error('REPLAY_DETECTED','A fresh timestamp and nonce are required.',409);try{DB::table('request_nonces')->insert(['installation_id'=>$installation->id,'nonce'=>$nonce,'expires_at'=>now()->addSeconds(config('office.nonce_lifetime_seconds')),'created_at'=>now(),'updated_at'=>now()]);}catch(\Throwable){SecurityEvent::create(['type'=>'replay_detected','license_id'=>$installation->license_id,'installation_id'=>$installation->id,'ip_address'=>$request->ip(),'request_id'=>$request->attributes->get('request_id'),'context'=>[],'occurred_at'=>now()]);return ApiResponse::error('REPLAY_DETECTED','Request nonce has already been used.',409);}return $next($request);} }
